"""install_v2_01 - installs the V2-01 files all-or-nothing and prints proof (hand-written, see docs/stages/V2-01.md).

Layer:   tooling
Stage:   V2-01
Flags:   none
Raises:  ValueError when the embedded payload is corrupt (main turns it into exit code 2)
Budget:  none
Tests:   tests/v2/installers/test_install_v2_01.py
"""

import argparse
import base64
import hashlib
import json
import os
import sys
import zlib
from dataclasses import dataclass, field
from pathlib import Path

# zlib+base64 of {path: [sha256, base64 content]}; written by the builder, never by hand.
PAYLOAD = (
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
)


@dataclass
class Plan:
    create: list = field(default_factory=list)
    same: list = field(default_factory=list)
    differ: list = field(default_factory=list)


def load_payload() -> dict[str, bytes]:
    """Decode the embedded files and check each sha256; a damaged payload is refused."""
    manifest = json.loads(zlib.decompress(base64.b64decode("".join(PAYLOAD))).decode("utf-8"))
    files = {}
    for rel, (digest, text) in manifest.items():
        data = base64.b64decode(text)
        if hashlib.sha256(data).hexdigest() != digest:
            raise ValueError(f"payload corrupt: {rel}")
        files[rel] = data
    return files


def make_plan(files: dict[str, bytes], root: Path) -> Plan:
    plan = Plan()
    for rel, data in sorted(files.items()):
        target = root / rel
        if not target.exists():
            plan.create.append(rel)
        elif target.read_bytes() == data:
            plan.same.append(rel)
        else:
            plan.differ.append(rel)
    return plan


def write_all(files: dict[str, bytes], root: Path, rels: list[str]) -> None:
    """Stage every file next to its target, then rename them in; on any failure undo it all."""
    staged: list[tuple[Path, Path]] = []
    done: list[Path] = []
    try:
        for rel in rels:
            target = root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            temp = target.with_name(target.name + ".v2tmp")
            temp.write_bytes(files[rel])
            staged.append((temp, target))
        for temp, target in staged:
            os.replace(temp, target)
            done.append(target)
    except OSError:
        for temp, _target in staged:
            temp.unlink(missing_ok=True)
        for target in done:
            target.unlink(missing_ok=True)
        raise


def run(files: dict[str, bytes], root: Path, dry_run: bool) -> int:
    if not (root / "src" / "app").is_dir():
        print(f"REFUSE: {root} does not look like cf-worker/ (no src/app). Use --root.")
        return 1
    plan = make_plan(files, root)
    for rel in plan.differ:
        print(f"REFUSE {rel}: exists and differs from what V2-01 expects")
    if plan.differ:
        print(f"summary: nothing was written; refused={len(plan.differ)}")
        return 1
    if not dry_run:
        write_all(files, root, plan.create)
    verb = "WOULD CREATE" if dry_run else "CREATED"
    for rel in plan.create:
        print(f"{verb} {rel} sha256={hashlib.sha256(files[rel]).hexdigest()[:12]}")
    for rel in plan.same:
        print(f"UNCHANGED {rel}")
    print(f"summary: created={0 if dry_run else len(plan.create)} would_create={len(plan.create) if dry_run else 0} "
          f"unchanged={len(plan.same)} refused=0")
    return 0


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(prog="install_v2_01", description="Install the V2-01 files (all or nothing).")
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[2], help="cf-worker/ directory")
    parser.add_argument("--dry-run", action="store_true", help="show what would happen, write nothing")
    args = parser.parse_args(argv)
    try:
        files = load_payload()
    except (ValueError, zlib.error) as exc:
        print(f"ERROR: the installer payload is damaged ({exc}); download it again.")
        return 2
    try:
        return run(files, args.root.resolve(), args.dry_run)
    except OSError as exc:
        print(f"ERROR: a write failed and everything was undone: {exc}")
        return 2


if __name__ == "__main__":
    sys.exit(main())
